"""Filter expression module for vector store metadata filtering.

Provides a small, composable, JSON-serializable expression tree that can be
evaluated against a record (``dict``) and a fluent builder (``F``) for
constructing conditions with natural Python operators.
"""

from __future__ import annotations

from enum import Enum
from typing import Annotated, Any, Literal, Union

from pydantic import BaseModel, Field

__all__ = [
    "AndExpr",
    "Condition",
    "F",
    "FilterExpr",
    "NotExpr",
    "Operator",
    "OrExpr",
]


class Operator(str, Enum):
    """Enum of comparison operators supported by a :class:`Condition`."""

    eq = "eq"
    ne = "ne"
    gt = "gt"
    gte = "gte"
    lt = "lt"
    lte = "lte"
    in_ = "in_"


class FilterExpr(BaseModel):
    """Abstract base class for all filter expressions.

    Supports the ``&`` (AND), ``|`` (OR) and ``~`` (NOT) operators. Combining
    with ``&``/``|`` produces flat :class:`AndExpr`/:class:`OrExpr` nodes rather
    than nested ones.
    """

    def evaluate(self, record: dict) -> bool:
        """Evaluate the expression against a record."""
        raise NotImplementedError

    def __and__(self, other: FilterExpr) -> AndExpr:
        """Combine two expressions with a logical AND, flattening children."""
        left = list(self.and_) if isinstance(self, AndExpr) else [self]
        right = list(other.and_) if isinstance(other, AndExpr) else [other]
        return AndExpr(and_=[*left, *right])

    def __or__(self, other: FilterExpr) -> OrExpr:
        """Combine two expressions with a logical OR, flattening children."""
        left = list(self.or_) if isinstance(self, OrExpr) else [self]
        right = list(other.or_) if isinstance(other, OrExpr) else [other]
        return OrExpr(or_=[*left, *right])

    def __invert__(self) -> FilterExpr:
        """Negate the expression."""
        return NotExpr(not_=self)


class Condition(FilterExpr):
    """A single field comparison condition."""

    type: Literal["condition"] = "condition"
    field: str
    operator: Operator
    value: Any = None

    def evaluate(self, record: dict) -> bool:
        """Apply the operator comparison; ``False`` if the field is absent."""
        if self.field not in record:
            return False
        actual = record[self.field]
        match self.operator:
            case Operator.eq:
                return actual == self.value
            case Operator.ne:
                return actual != self.value
            case Operator.gt:
                return actual > self.value
            case Operator.gte:
                return actual >= self.value
            case Operator.lt:
                return actual < self.value
            case Operator.lte:
                return actual <= self.value
            case Operator.in_:
                return actual in self.value
        return False


# Discriminated union of every concrete expression type. Using the ``type``
# literal as the discriminator lets Pydantic reconstruct the correct subclass
# during ``model_validate`` (i.e. survive a JSON round-trip).
FilterExprType = Annotated[
    Union["Condition", "AndExpr", "OrExpr", "NotExpr"],
    Field(discriminator="type"),
]


class AndExpr(FilterExpr):
    """Logical AND of a list of filter expressions."""

    type: Literal["and"] = "and"
    and_: list[FilterExprType]

    def evaluate(self, record: dict) -> bool:
        """Return ``True`` only if every sub-expression evaluates to ``True``."""
        return all(expr.evaluate(record) for expr in self.and_)


class OrExpr(FilterExpr):
    """Logical OR of a list of filter expressions."""

    type: Literal["or"] = "or"
    or_: list[FilterExprType]

    def evaluate(self, record: dict) -> bool:
        """Return ``True`` if at least one sub-expression evaluates to ``True``."""
        return any(expr.evaluate(record) for expr in self.or_)


class NotExpr(FilterExpr):
    """Logical NOT of a single filter expression."""

    type: Literal["not"] = "not"
    not_: FilterExprType

    def evaluate(self, record: dict) -> bool:
        """Return the negation of the inner expression."""
        return not self.not_.evaluate(record)

    def __invert__(self) -> FilterExpr:
        """Double-negation cancellation: ``~NotExpr(x)`` returns ``x``."""
        return self.not_


