class _FieldProxy:
    """Proxy returned by ``F.<field>`` that builds :class:`Condition` objects."""

    def __init__(self, name: str):
        self._name = name

    def __eq__(self, value: Any) -> Condition:  # type: ignore[override]
        return Condition(field=self._name, operator=Operator.eq, value=value)

    def __ne__(self, value: Any) -> Condition:  # type: ignore[override]
        return Condition(field=self._name, operator=Operator.ne, value=value)

    def __gt__(self, value: Any) -> Condition:
        return Condition(field=self._name, operator=Operator.gt, value=value)

    def __ge__(self, value: Any) -> Condition:
        return Condition(field=self._name, operator=Operator.gte, value=value)

    def __lt__(self, value: Any) -> Condition:
        return Condition(field=self._name, operator=Operator.lt, value=value)

    def __le__(self, value: Any) -> Condition:
        return Condition(field=self._name, operator=Operator.lte, value=value)

    def in_(self, values: list[Any]) -> Condition:
        """Build a membership condition against ``values``."""
        return Condition(field=self._name, operator=Operator.in_, value=list(values))

    __hash__ = None  # type: ignore[assignment]


