    """Fluent builder: ``F.some_field`` yields a :class:`_FieldProxy`."""

    def __getattr__(self, name: str) -> _FieldProxy:
        if name.startswith("__") and name.endswith("__"):
            msg = name
            raise AttributeError(msg)
        return _FieldProxy(name)


