"""The LanceDB vector storage implementation package."""

from datetime import datetime, timezone
from typing import Any

import lancedb
import numpy as np
import pyarrow as pa

from graphrag_vectors.filtering import FilterExpr
from graphrag_vectors.timestamp import (
    TIMESTAMP_FIELDS,
    _timestamp_fields_for,
    explode_timestamp,
)
from graphrag_vectors.vector_store import (
    VectorStore,
    VectorStoreDocument,
    VectorStoreSearchResult,
)

# Mapping of the declarative field type strings to PyArrow types. ``date`` is
# stored as its raw ISO string alongside its exploded numeric/string components.
_ARROW_TYPES: dict[str, pa.DataType] = {
    "str": pa.string(),
    "int": pa.int64(),
    "float": pa.float64(),
    "bool": pa.bool_(),
    "date": pa.string(),
}

# The built-in lifecycle timestamp fields, always present on every document.
_CREATE_DATE = "create_date"
_UPDATE_DATE = "update_date"


class LanceDBVectorStore(VectorStore):
    """LanceDB vector storage implementation."""

    def __init__(
        self,
        db_uri: str = "lancedb",
        fields: dict[str, str] | None = None,
        **kwargs: Any,
    ):
        super().__init__(**kwargs)
        self.db_uri = db_uri
        self.fields = fields or {}

        # The set of raw date-typed fields (built-ins + user-declared) that get
        # exploded into timestamp components.
        self._date_fields = [
            _CREATE_DATE,
            _UPDATE_DATE,
            *[name for name, ftype in self.fields.items() if ftype == "date"],
        ]

        # The full metadata column map (name -> type string), excluding the id
        # and vector columns. Order is stable for deterministic schemas.
        field_map: dict[str, str] = {
            _CREATE_DATE: "str",
            _UPDATE_DATE: "str",
            **TIMESTAMP_FIELDS,
        }
        for name, ftype in self.fields.items():
            if ftype == "date":
                field_map[name] = "str"
                field_map.update(_timestamp_fields_for(name))
            else:
                field_map[name] = ftype
        self._field_map = field_map

    def connect(self) -> Any:
        """Connect to the vector storage."""
        self.db_connection = lancedb.connect(self.db_uri)

        if self.index_name and self.index_name in self.db_connection.table_names():
            self.document_collection = self.db_connection.open_table(self.index_name)

    def _arrow_schema(self) -> pa.Schema:
        """Build the PyArrow schema for the backing table."""
        schema_fields = [
            pa.field(self.id_field, pa.string()),
            pa.field(self.vector_field, pa.list_(pa.float32(), self.vector_size)),
        ]
        schema_fields.extend(
            pa.field(name, _ARROW_TYPES[ftype])
            for name, ftype in self._field_map.items()
        )
        return pa.schema(schema_fields)

    def create_index(self) -> None:
        """Create an empty index (zero documents) with the configured schema."""
        self.document_collection = self.db_connection.create_table(
            self.index_name if self.index_name else "",
            schema=self._arrow_schema(),
            mode="overwrite",
        )

    def _build_row(
        self,
        document: VectorStoreDocument,
        *,
        auto_create_date: bool = True,
    ) -> dict[str, Any]:
        """Build a full column->value row dict for a document, exploding dates."""
        data = dict(document.data or {})

        if auto_create_date and not data.get(_CREATE_DATE):
            data[_CREATE_DATE] = datetime.now(timezone.utc).isoformat()

        # Explode every date field into its timestamp components.
        exploded: dict[str, Any] = {}
        for date_field in self._date_fields:
            exploded.update(explode_timestamp(data.get(date_field), date_field))

        row: dict[str, Any] = {
            self.id_field: str(document.id),
            self.vector_field: (
                np.asarray(document.vector, dtype=np.float32)
                if document.vector is not None
                else None
            ),
        }
        for name in self._field_map:
            if name in exploded:
                row[name] = exploded[name]
            elif name in data:
                row[name] = data[name]
            else:
